import{_ as t,c as a,o as s,ag as i}from"./chunks/framework.Ci10AEOF.js";const n="/docs-website/assets/code_templates.BzCpCb95.png",m=JSON.parse('{"title":"Code Templates","description":"Reusable code libraries","frontmatter":{"title":"Code Templates","description":"Reusable code libraries"},"headers":[],"relativePath":"engine/code_templates.md","filePath":"engine/code_templates.md","lastUpdated":1793057853000}'),l={name:"engine/code_templates.md"};function r(o,e,p,d,h,c){return s(),a("div",null,e[0]||(e[0]=[i(`<h1 id="code-templates" tabindex="-1">Code Templates <a class="header-anchor" href="#code-templates" aria-label="Permalink to &quot;Code Templates&quot;">​</a></h1><p>Code templates are reusable code snippets and function libraries that can be shared across multiple channels.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Code templates are organized into <strong>libraries</strong>. Each library is enabled for specific channels. Global scripts receive the matching templates from every library.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Code Template Library</span></span>
<span class="line"><span>├── Code Template 1 (Function)</span></span>
<span class="line"><span>├── Code Template 2 (Compiled Code Block)</span></span>
<span class="line"><span>└── Code Template 3 (Drag-and-Drop Code Block)</span></span></code></pre></div><h2 id="managing-code-templates" tabindex="-1">Managing code templates <a class="header-anchor" href="#managing-code-templates" aria-label="Permalink to &quot;Managing code templates&quot;">​</a></h2><h3 id="code-template-panel" tabindex="-1">Code template panel <a class="header-anchor" href="#code-template-panel" aria-label="Permalink to &quot;Code template panel&quot;">​</a></h3><p>Click <strong>Edit Code Templates</strong> in the task panel of the <strong>Channels</strong> view:</p><ul><li>View all libraries and their templates</li><li>Create, edit, and delete templates</li><li>Assign libraries to channels</li></ul><p><img src="`+n+`" alt="The Code Templates view with one library holding a function template, its code, and the script contexts it is available in"></p><h3 id="creating-a-library" tabindex="-1">Creating a library <a class="header-anchor" href="#creating-a-library" aria-label="Permalink to &quot;Creating a library&quot;">​</a></h3><ol><li>Open the code templates panel with <strong>Edit Code Templates</strong></li><li>Click <strong>New Library</strong>. The library is named Library 1 (then Library 2, and so on)</li><li>Rename the library in the tree</li><li>Select which channels should have access to this library</li></ol><h3 id="creating-a-code-template" tabindex="-1">Creating a code template <a class="header-anchor" href="#creating-a-code-template" aria-label="Permalink to &quot;Creating a code template&quot;">​</a></h3><ol><li>Select a library or a template in the tree</li><li>Click <strong>New Code Template</strong>. The template is named Template 1 (then Template 2, and so on); rename it in the tree</li><li>Configure: <ul><li><strong>Library</strong>: The library the template belongs to</li><li><strong>Type</strong>: Function, Drag-and-Drop Code Block, or Compiled Code Block, plus one entry for each code template type that an installed extension adds</li><li><strong>Context</strong>: Where it can be used (see below)</li><li><strong>Code</strong>: The JavaScript implementation</li></ul></li></ol><h2 id="template-types" tabindex="-1">Template types <a class="header-anchor" href="#template-types" aria-label="Permalink to &quot;Template types&quot;">​</a></h2><h3 id="function" tabindex="-1">Function <a class="header-anchor" href="#function" aria-label="Permalink to &quot;Function&quot;">​</a></h3><p>A named function that can be called from channel scripts. Functions are automatically added to the script context of assigned channels.</p><p>The engine parses the comment block at the top of a Function template. The text before the first <code>@</code> tag becomes the template&#39;s description, and the <code>@param {type} name - text</code> and <code>@return {type} text</code> lines supply the parameter and return details that the Reference List and the editor&#39;s auto-complete show for the function. The format the engine expects is the one below, each line indented and without a leading asterisk. It is what a new Function template starts with, and what the <strong>Generate JSDoc</strong> / <strong>Update JSDoc</strong> button in the template editor writes. With a <code>*</code> at the start of each line no <code>@</code> tag is recognized: the whole comment, asterisks included, becomes the description, and every parameter shows as type <code>Any</code> with no description. The block is stripped from the code before the function is added to channel scripts.</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/**</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    Formats a patient name from HL7 components.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    @param</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> {String}</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> lastName</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> - Family name, PID.5.1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    @param</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> {String}</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> firstName</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> - Given name, PID.5.2</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    @return</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> {String}</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> The name as LAST, First</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">*/</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> formatPatientName</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">lastName</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">firstName</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> lastName.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">toUpperCase</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;, &#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> firstName;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The call below runs in the source or destination transformer of a channel whose inbound data type is HL7 v2, with the template&#39;s library assigned to the channel and the Filter / Transformer context selected on the template. <code>msg</code> is the inbound message, which the engine serializes into an E4X XML object before the transformer runs (see <a href="./script_scope_and_user_api.html#message-msg">Message (<code>msg</code>)</a>); the <code>PID.5.1</code> and <code>PID.5.2</code> element names exist only under HL7 v2. No outbound template is needed. <code>$c</code> is the channel map shorthand the engine adds to every script: one argument reads a key, two arguments write one.</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> patientName </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> formatPatientName</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    msg[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;PID&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">][</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;PID.5&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">][</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;PID.5.1&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">].</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">toString</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(),</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    msg[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;PID&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">][</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;PID.5&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">][</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;PID.5.2&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">].</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">toString</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$c</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;patientName&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, patientName);</span></span></code></pre></div><p>For a PID.5 of <code>DOE^JOHN</code> the channel map entry <code>patientName</code> holds <code>DOE, JOHN</code>, shown on the message in the Message Browser&#39;s Mappings tab.</p><h3 id="compiled-code-block" tabindex="-1">Compiled code block <a class="header-anchor" href="#compiled-code-block" aria-label="Permalink to &quot;Compiled code block&quot;">​</a></h3><p>A block of code that is compiled and added to the script context, similar to a function. Unlike a function, it cannot be dragged from the reference list. For example, it can hold shared initialization code or constants.</p><h3 id="drag-and-drop-code-block" tabindex="-1">Drag-and-drop code block <a class="header-anchor" href="#drag-and-drop-code-block" aria-label="Permalink to &quot;Drag-and-drop code block&quot;">​</a></h3><p>A code block that can be dragged from the reference list into the script editor. Unlike Functions and Compiled Code Blocks, Drag-and-Drop Code Blocks are <strong>not</strong> automatically added to the script context.</p><h2 id="execution-contexts" tabindex="-1">Execution contexts <a class="header-anchor" href="#execution-contexts" aria-label="Permalink to &quot;Execution contexts&quot;">​</a></h2><p>Code templates can be restricted to specific contexts. There are 15 contexts in four groups:</p><table tabindex="0"><thead><tr><th>Group</th><th>Context</th></tr></thead><tbody><tr><td><strong>Global Scripts</strong></td><td>Deploy Script</td></tr><tr><td><strong>Global Scripts</strong></td><td>Undeploy Script</td></tr><tr><td><strong>Global Scripts</strong></td><td>Preprocessor Script</td></tr><tr><td><strong>Global Scripts</strong></td><td>Postprocessor Script</td></tr><tr><td><strong>Channel Scripts</strong></td><td>Deploy Script</td></tr><tr><td><strong>Channel Scripts</strong></td><td>Undeploy Script</td></tr><tr><td><strong>Channel Scripts</strong></td><td>Preprocessor Script</td></tr><tr><td><strong>Channel Scripts</strong></td><td>Postprocessor Script</td></tr><tr><td><strong>Channel Scripts</strong></td><td>Attachment Script</td></tr><tr><td><strong>Channel Scripts</strong></td><td>Batch Script</td></tr><tr><td><strong>Source Connector</strong></td><td>Receiver Script(s)</td></tr><tr><td><strong>Source Connector</strong></td><td>Filter / Transformer Script</td></tr><tr><td><strong>Destination Connector</strong></td><td>Filter / Transformer Script</td></tr><tr><td><strong>Destination Connector</strong></td><td>Dispatcher Script</td></tr><tr><td><strong>Destination Connector</strong></td><td>Response Transformer Script</td></tr></tbody></table><p>A template is available only in the contexts selected for it.</p><h2 id="library-assignment" tabindex="-1">Library assignment <a class="header-anchor" href="#library-assignment" aria-label="Permalink to &quot;Library assignment&quot;">​</a></h2><p>A library applies to the channels it is assigned to. The assignment does not apply to global scripts, which receive the matching Function and Compiled Code Block templates from every library.</p><ol><li>Select the library in the tree</li><li>Check the channels that should have access</li><li>Check <strong>[New Channels]</strong> to include every channel not explicitly unchecked, including channels created or imported later</li><li>Save and redeploy affected channels</li></ol><p>A channel&#39;s own assignments are also editable from the channel editor: <strong>Set Dependencies</strong> opens the Channel Dependencies dialog, whose <strong>Code Template Libraries</strong> tab lists every library with Select All and Deselect All links.</p><p>A change to a code template reaches a channel only when the channel is redeployed, because templates are compiled into the channel&#39;s scripts at deploy. The Dashboard highlights <strong>Rev Δ</strong> for a channel whose code templates have changed since it was deployed.</p><h2 id="import-export" tabindex="-1">Import / export <a class="header-anchor" href="#import-export" aria-label="Permalink to &quot;Import / export&quot;">​</a></h2><h3 id="gui" tabindex="-1">GUI <a class="header-anchor" href="#gui" aria-label="Permalink to &quot;GUI&quot;">​</a></h3><ul><li>Right-click a library or template to export as XML</li><li>Use <strong>Import</strong> to load from XML files</li></ul><h3 id="cli" tabindex="-1">CLI <a class="header-anchor" href="#cli" aria-label="Permalink to &quot;CLI&quot;">​</a></h3><p>These commands are typed at the prompt of the CLI shell, which connects to a running server (see <a href="./command_line_interface.html#launching-the-cli">Launching the CLI</a>); they are not operating-system commands. <code>path</code> is quoted when it contains spaces. Each command is described under <a href="./command_line_interface.html#code-templates">Code templates</a> on that page.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>codetemplate library list [includecodetemplates]</span></span>
<span class="line"><span>codetemplate list</span></span>
<span class="line"><span>codetemplate import &quot;path&quot; [force]</span></span>
<span class="line"><span>codetemplate library import &quot;path&quot; [force]</span></span>
<span class="line"><span>codetemplate export id|name &quot;path&quot;</span></span>
<span class="line"><span>codetemplate library export id|name|* &quot;path&quot;</span></span>
<span class="line"><span>codetemplate remove id|name</span></span>
<span class="line"><span>codetemplate library remove id|name|*</span></span></code></pre></div><h2 id="reference-list" tabindex="-1">Reference list <a class="header-anchor" href="#reference-list" aria-label="Permalink to &quot;Reference list&quot;">​</a></h2><p>The script editor has a <strong>Reference List</strong> panel that lists:</p><ul><li>Available code template functions</li><li>Built-in utility functions (<code>ChannelUtil</code>, <code>DateUtil</code>, <code>FileUtil</code>, etc.)</li><li>Variable references (<code>msg</code>, <code>tmp</code>, <code>channelMap</code>, etc.)</li><li>Example code snippets</li></ul><p>See <a href="./javascript_editor.html#reference-list">Reference list</a> on the JavaScript Editor page.</p>`,45)]))}const k=t(l,[["render",r]]);export{m as __pageData,k as default};
